+const char* const kClosed = "agent: agent is closed";
+const char* const kCancelled = "agent: call cancelled";
+
+bool IsClosed(const std::string& e) { return e == kClosed; }
+bool IsCancelled(const std::string& e) { return e == kCancelled; }
+
+namespace {
