+// Closes the session on every failure path of Open; empty once the agent owns it.
+struct SessionGuard {
+  std::unique_ptr<infer::Session>& s;
+  ~SessionGuard() {
+    if (!s) return;
+    try {
+      s->Close();
+    } catch (...) {
+    }
+  }
+};
