+std::string CheckInstructions(const std::string& ins) {
+  if (ud::IsBlank(ins)) return kBlankIns;
+  if (!ud::ValidUtf8(ins)) return "'instructions' is not valid UTF-8; a Python str always is";
+  return "";
+}
