+std::string ReplaceAll(std::string s, const std::string& from, const std::string& to) {
+  if (from.empty()) return s;
+  std::string out;
+  for (size_t at = 0;;) {
+    size_t hit = s.find(from, at);
+    if (hit == std::string::npos) {
+      out.append(s, at, std::string::npos);
+      return out;
+    }
+    out.append(s, at, hit - at);
+    out += to;
+    at = hit + from.size();
+  }
+}
