+  if (tok == nullptr) return r;
+  auto s = std::make_unique<StubSession>();
+  r.st = s->state();
+  auto a = ag::Agent::OpenParts(config, *tok, std::move(s));
+  EXPECT_TRUE(a.ok()) << (a.ok() ? "" : a.error());
+  if (a.ok()) r.agent = std::move(a).value();
+  return r;
+}
