+TEST_P(OnnxRig, SessionRunIsGuardedAgainstHostileBatches) {
+  const Rig& rig = kRigs[GetParam()];
+  NEED_RIG(rig, graph, dir);
+  auto s = laya::onnx::Open(graph);
+  ASSERT_TRUE(s.ok()) << s.error();
